{"cards": [{"node_code": "N_2869d2a0495b06bd", "definition": "聚焦交通系统的数字化架构、软硬件集成、数字孪生构建及专业软件工具开发，旨在实现交通系统的整体协同、虚实映射与工程辅助设计。", "boundary": "本节点侧重“系统集成”与“数字化工具”，关注如何将感知、通信、计算等模块整合为完整的智能运输系统（ITS），以及利用数字孪生和软件进行仿真与辅助设计。不包含底层的通信协议细节（归入交通信息通信）、具体的算法模型推导（归入建模与仿真或运筹优化）或单一硬件设备的制造原理。", "includes": ["智能运输系统（ITS）的体系架构设计、模块集成与互操作接口标准", "交通数字孪生系统的建模、虚实交互及可视化展示技术", "交通专业软件、计算机辅助设计（CAD）及信息系统开发工具"], "excludes": ["底层通信网络协议、网络安全防护技术（归入交通信息通信与网络安全）", "交通流微观/宏观仿真算法原理及数学模型构建（归入交通系统建模与仿真）", "具体的路径规划、调度优化算法（归入交通运筹优化与决策）"], "sibling_distinctions": [{"other_code": "N_b47b0c9623a45cd7", "rule": "本节点关注系统层面的架构集成与数字孪生应用；兄弟节点关注底层通信链路、数据传输协议及网络安全机制。"}, {"other_code": "N_52983288d081e3cc", "rule": "本节点关注仿真结果的可视化、数字孪生平台构建及软件工具；兄弟节点关注仿真背后的数学模型、机理分析及算法验证。"}, {"other_code": "N_48e0933413942498", "rule": "本节点提供通用的系统集成框架与数字化工具；兄弟节点特指车路协同、自动驾驶等特定场景下的系统实现与控制策略。"}], "cross_boundary_rule": "涉及数字孪生中的具体交通流仿真算法归入建模与仿真，数字孪生平台架构与可视化归入本节点；涉及ITS中的通信协议归入信息通信，ITS整体架构与集成归入本节点。"}, {"node_code": "N_ed5bedd59cec3635", "definition": "研究交通运输系统中的能源供给、转换、存储技术，以及交通活动对环境的影响评估、碳减排技术与全生命周期碳管理方法。", "boundary": "本节点侧重“能源”与“环境”两个维度的系统工程问题，关注交通系统与能源系统的融合（如车网互动、新能源补给）及交通碳排放的量化、监测与控制。不包含车辆本身的动力机械原理（归入具体运输方式节点）或纯环境科学理论（非交通专用）。", "includes": ["交通能源融合技术，如新能源交通补给、交通储能系统与能碳管理", "交通系统碳中和技术、全生命周期碳评价方法及减排策略", "交通活动对环境影响的监测、评估及绿色交通系统设计"], "excludes": ["车辆发动机、电池等动力总成的机械/电化学原理（归入铁路/公路/航空等具体运输方式节点）", "纯环境科学、大气化学或生态学理论（非交通专用）", "交通能源的经济性分析与市场机制（归入交通运输经济）"], "sibling_distinctions": [{"other_code": "N_49933e9d2425536a", "rule": "本节点关注能源供给与环境指标；兄弟节点关注基础设施的物理状态监测、维护与寿命管理。"}, {"other_code": "N_514c8d74b17bfdc2", "rule": "本节点关注能源与环境数据的宏观分析与系统优化；兄弟节点关注感知硬件、定位技术及物联网底层连接。"}], "cross_boundary_rule": "涉及交通能源系统的控制算法归入本节点，若侧重能源经济政策归入交通运输经济；涉及交通碳排放的监测传感器归入感知定位，碳排放计算模型与管理归入本节点。"}, {"node_code": "N_49933e9d2425536a", "definition": "利用智能感知、数据分析及自动化技术，对交通基础设施（如道路、桥梁、轨道、隧道）进行状态监测、健康评估、预测性维护及自动化运维作业。", "boundary": "本节点侧重“基础设施”的“运维”环节，强调基于数据的设施状态管理、寿命预测及自动化/机器人辅助维护。不包含基础设施的初始设计、施工建造技术（归入具体运输方式的基础设施节点）或纯机械维修工艺。", "includes": ["交通设施的结构健康监测、损伤识别及预测性维护算法", "用于交通设施巡检、检测及维护的机器人、无人机等自动化装备", "交通基础设施运维管理系统、数字档案及全生命周期管理技术"], "excludes": ["道路、桥梁、轨道等基础设施的结构设计、材料力学及施工建造技术（归入铁路/公路等具体节点）", "车辆、船舶、飞机等移动载运工具的维修保养（归入具体运输方式节点）", "纯土木工程材料科学或通用机械维修理论"], "sibling_distinctions": [{"other_code": "N_2869d2a0495b06bd", "rule": "本节点关注设施物理状态的监测与维护执行；兄弟节点关注系统架构、数字孪生平台及软件工具开发。"}, {"other_code": "N_514c8d74b17bfdc2", "rule": "本节点应用感知技术进行设施状态评估；兄弟节点研究感知传感器原理、定位算法及物联网通信协议。"}], "cross_boundary_rule": "涉及设施监测的传感器硬件归入感知定位，监测数据处理与维护决策归入本节点；涉及运维机器人的机械结构归入具体运输方式或通用机械，机器人控制与运维策略归入本节点。"}]}
